"124 :   private void inferArguments(Scope functionScope) {
125 :     Node functionNode = functionScope.getRootNode();
126 :     Node astParameters = functionNode.getFirstChild().getNext();
127 :     Node iifeArgumentNode = null;
128 : 
129 :     if (NodeUtil.isCallOrNewTarget(functionNode)) {
130 :       iifeArgumentNode = functionNode.getNext();
131 :     }
132 : 
133 :     FunctionType functionType =
134 :         JSType.toMaybeFunctionType(functionNode.getJSType());
135 :     if (functionType != null) {
136 :       Node parameterTypes = functionType.getParametersNode();
137 :       if (parameterTypes != null) {
138 :         Node parameterTypeNode = parameterTypes.getFirstChild();
139 :         for (Node astParameter : astParameters.children()) {
140 :           Var var = functionScope.getVar(astParameter.getString());
141 :           Preconditions.checkNotNull(var);
142 :           if (var.isTypeInferred() &&
143 :               var.getType() == unknownType) {
144 :             JSType newType = null;
145 : 
146 :             if (iifeArgumentNode != null) {
147 :               newType = iifeArgumentNode.getJSType();
148 :             } else if (parameterTypeNode != null) {
149 :               newType = parameterTypeNode.getJSType();
150 :             }
151 : 
152 :             if (newType != null) {
153 :               var.setType(newType);
154 :               astParameter.setJSType(newType);
155 :             }
156 :           }
157 : 
158 :           if (parameterTypeNode != null) {
159 :             parameterTypeNode = parameterTypeNode.getNext();
160 :           }
161 :           if (iifeArgumentNode != null) {
162 :             iifeArgumentNode = iifeArgumentNode.getNext();
163 :           }
164 :         }
165 :       }
166 :     }
